def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    if n == 0:
        return 1

    chars = list(dict.fromkeys(alphabet))
    if not chars:
        return 0

    char_set = set(chars)

    nexts = [{}]
    out = [False]

    for pat in set(banned):
        if not all(ch in char_set for ch in pat):
            continue
        node = 0
        for ch in pat:
            if ch not in nexts[node]:
                nexts[node][ch] = len(nexts)
                nexts.append({})
                out.append(False)
            node = nexts[node][ch]
        out[node] = True

    size = len(nexts)
    c_count = len(chars)

    go = [[0] * c_count for _ in range(size)]
    fail = [0] * size
    queue = []

    for i, ch in enumerate(chars):
        u = nexts[0].get(ch)
        if u is None:
            go[0][i] = 0
        else:
            go[0][i] = u
            fail[u] = 0
            queue.append(u)

    head = 0
    while head < len(queue):
        v = queue[head]
        head += 1

        if out[fail[v]]:
            out[v] = True

        for i, ch in enumerate(chars):
            u = nexts[v].get(ch)
            if u is None:
                go[v][i] = go[fail[v]][i]
            else:
                go[v][i] = u
                fail[u] = go[fail[v]][i]
                queue.append(u)

    if out[0]:
        return 0

    good = [s for s in range(size) if not out[s]]
    m = len(good)
    index = {s: i for i, s in enumerate(good)}

    mat = [[0] * m for _ in range(m)]
    for s in good:
        i = index[s]
        row = mat[i]
        for ci in range(c_count):
            t = go[s][ci]
            if not out[t]:
                row[index[t]] = (row[index[t]] + 1) % MOD

    vec = [0] * m
    vec[index[0]] = 1

    def mat_mul(A, B):
        sz = len(A)
        C = [[0] * sz for _ in range(sz)]
        for i in range(sz):
            Ci = C[i]
            Ai = A[i]
            for k in range(sz):
                a = Ai[k]
                if a:
                    Bk = B[k]
                    for j in range(sz):
                        Ci[j] += a * Bk[j]
            for j in range(sz):
                Ci[j] %= MOD
        return C

    def vec_mul(v, M):
        sz = len(v)
        res = [0] * sz
        for i in range(sz):
            a = v[i]
            if a:
                Mi = M[i]
                for j in range(sz):
                    res[j] += a * Mi[j]
        for j in range(sz):
            res[j] %= MOD
        return res

    e = n
    while e:
        if e & 1:
            vec = vec_mul(vec, mat)
        e >>= 1
        if e:
            mat = mat_mul(mat, mat)

    return sum(vec) % MOD
